args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?later ?laterLabel ?laterBirthDate WHERE {
  VALUES (?a ?b) {
    (dbr:Tadeusz_Śliwak dbr:Michel_Le_Denmat)
    (dbr:Michel_Le_Denmat dbr:Tadeusz_Śliwak)
  }
  ?a dbo:birthDate ?aDate .
  ?b dbo:birthDate ?bDate .
  FILTER(xsd:date(?aDate) > xsd:date(?bDate))
  BIND(?a AS ?later)
  BIND(?aDate AS ?laterBirthDate)
  OPTIONAL { ?later rdfs:label ?laterLabel . FILTER(langMatches(lang(?laterLabel), "en")) }
}

